CREATE TABLE users(row_id TEXT PRIMARY KEY,line_id TEXT UNIQUE,role TEXT,network_id TEXT,referrer_id TEXT,name TEXT,phone TEXT);
INSERT INTO users VALUES('owner-a','owner-a','store','owner-a','','合成甲店',''),('owner-b','owner-b','store','owner-b','','合成乙店',''),('member-a','member-a','user','owner-a','','合成學員','');
CREATE TABLE activities(activity_id TEXT PRIMARY KEY,name TEXT,type TEXT,fee_type TEXT,price INTEGER,start_time TEXT,end_time TEXT,description TEXT,image_url TEXT,image_ratio TEXT,creator_id TEXT,network_id TEXT,status TEXT,is_series INTEGER,series_id TEXT DEFAULT '',batch_name TEXT DEFAULT '',batch_limit INTEGER,nfc_checkin_start TEXT,nfc_checkin_end TEXT,nfc_same_day_only INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,ever_unpublished INTEGER DEFAULT 0,visibility TEXT DEFAULT 'network');
INSERT INTO activities(activity_id,name,creator_id,network_id,status) VALUES('A','合成活動','owner-a','owner-a','上架'),('COURSE','合成課程','owner-a','owner-a','上架'),('PARENT','合成多梯次','owner-a','owner-a','上架'),('CHILD','合成子梯次','owner-a','owner-a','上架');
UPDATE activities SET series_id='PARENT' WHERE activity_id='CHILD';
CREATE TABLE registrants(row_id TEXT PRIMARY KEY,line_id TEXT,activity_id TEXT,activity_name TEXT,name TEXT,phone TEXT,identity TEXT,amount INTEGER,payment_status TEXT,start_time TEXT,description TEXT,image_url TEXT,status TEXT,checked_in INTEGER DEFAULT 0,nfc_checkin_time TEXT DEFAULT '',nfc_checkin_source TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT INTO registrants(row_id,line_id,activity_id,name,status) VALUES('REG_A','member-a','A','合成學員','active'),('REG_COURSE','member-a','COURSE','合成學員','active'),('REG_CHILD','member-a','CHILD','合成學員','active'),('REG_CANCELLED','member-a','A','合成取消','cancelled');
